const item = $input.first().json;

const summary = item.summary || '';
const description = item.description || '';
const start = item.start?.dateTime || item.start?.date || '';

// Filtro: solo procesar eventos que vengan de las citas de IMEF en Calendly.
// TODO: ajusta este texto si el evento sincronizado por Calendly no incluye "IMEF"
// en el titulo o la descripcion (revisa el primer evento real de prueba).
const esIMEF = /imef/i.test(summary) || /imef/i.test(description);
if (!esIMEF) {
  return [];
}

const modalidad = /presencial/i.test(summary + description)
  ? 'Visita presencial'
  : 'Entrevista en línea';

// Calendly suele nombrar el evento "Nombre del invitado and Nombre del organizador"
const nombreMatch = summary.match(/^(.*?)\s+(and|y)\s+/i);
const nombre = nombreMatch ? nombreMatch[1].trim() : summary;

// Busca la respuesta a la pregunta personalizada "Teléfono" en la descripcion del evento.
// TODO: ajusta el patron si el texto exacto que usa Calendly es distinto.
const telMatch = description.match(/(Tel[eé]fono|WhatsApp)[^\n:]*:?\s*([+\d\s()-]{7,})/i);
const telefono = telMatch ? telMatch[2].trim() : '';

const startDate = start ? new Date(start) : null;
const fechaHoraMx = startDate
  ? new Intl.DateTimeFormat('es-MX', {
      timeZone: 'America/Mexico_City',
      dateStyle: 'full',
      timeStyle: 'short',
    }).format(startDate)
  : '';

return [{
  json: {
    'Nombre': nombre,
    'Teléfono': telefono,
    'Modalidad': modalidad,
    'Día y hora de la cita': fechaHoraMx,
  }
}];
